package com.bitedash.controller; import com.bitedash.dto.*; import com.bitedash.service.ReviewService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/restaurants/{restaurantId}/reviews") public class ReviewController{private final ReviewService service; public ReviewController(ReviewService s){service=s;} @PostMapping public ReviewResponse add(@PathVariable Long restaurantId,@RequestHeader("X-User-Id") Long uid,@Valid @RequestBody ReviewRequest r){return service.add(uid,restaurantId,r);} @GetMapping public List<ReviewResponse> list(@PathVariable Long restaurantId){return service.list(restaurantId);}}
